import * as React from "react";

type CarouselProps = {
  intervalMs?: number;
  className?: string;
};

const carouselImages = [
  {
    jpgSrc: "/carousel/carousel_1.jpg",
    webpSrc: "/carousel/carousel_1.webp",
    width: 1197,
    height: 547,
  },
  {
    jpgSrc: "/carousel/carousel_2.jpg",
    webpSrc: "/carousel/carousel_2.webp",
    width: 794,
    height: 363,
  },
  {
    jpgSrc: "/carousel/carousel_3.jpg",
    webpSrc: "/carousel/carousel_3.webp",
    width: 799,
    height: 365,
  },
  {
    jpgSrc: "/carousel/carousel_4.jpg",
    webpSrc: "/carousel/carousel_4.webp",
    width: 3264,
    height: 1492,
  },
  {
    jpgSrc: "/carousel/carousel_5.jpg",
    webpSrc: "/carousel/carousel_5.webp",
    width: 800,
    height: 366,
  },
  {
    jpgSrc: "/carousel/carousel_6.jpg",
    webpSrc: "/carousel/carousel_6.webp",
    width: 1196,
    height: 547,
  },
  {
    jpgSrc: "/carousel/carousel_7.jpg",
    webpSrc: "/carousel/carousel_7.webp",
    width: 801,
    height: 366,
  },
];

const Carousel: React.FC<CarouselProps> = ({ intervalMs = 5000, className }) => {
  const [activeIndex, setActiveIndex] = React.useState(0);
  const activeImage = carouselImages[activeIndex];

  React.useEffect(() => {
    if (carouselImages.length <= 1) return;
    const timer = window.setInterval(() => {
      setActiveIndex((prev) => (prev + 1) % carouselImages.length);
    }, intervalMs);

    return () => window.clearInterval(timer);
  }, [intervalMs]);

  React.useEffect(() => {
    if (carouselImages.length <= 1) return;
    const nextIndex = (activeIndex + 1) % carouselImages.length;
    const preloadImage = new Image();
    preloadImage.src = carouselImages[nextIndex].webpSrc;
  }, [activeIndex]);

  return (
    <div className="w-full sm:w-[1024px] mx-auto mb-8" aria-label="Image Carousel">
      <div
        className="relative w-full overflow-hidden border border-dark_gray-200 bg-warm_ivory-500 shadow-lg"
        style={{ aspectRatio: "2 / 1" }}
      >
        <picture key={activeImage.jpgSrc}>
          <source srcSet={activeImage.webpSrc} type="image/webp" />
          <img
            src={activeImage.jpgSrc}
            width={activeImage.width}
            height={activeImage.height}
            alt={`Carousel image ${activeIndex + 1}`}
            className="absolute inset-0 h-full w-full object-cover"
            loading="eager"
            fetchPriority="high"
            decoding="async"
          />
        </picture>
      </div>
      {carouselImages.length > 1 && (
        <div className="mt-3 flex justify-center gap-2">
          {carouselImages.map((_, index) => (
            <button
              key={`indicator-${index}`}
              type="button"
              onClick={() => setActiveIndex(index)}
              aria-label={`Go to slide ${index + 1}`}
              className={`h-2.5 w-2.5 rounded-full border border-terracota-500 ${
                index === activeIndex
                  ? "bg-terracota-500"
                  : "bg-warm_ivory-500"
              }`}
            />
          ))}
        </div>
      )}
    </div>
  );
};

export default Carousel;
